// ------------------------------------------------------------
//  Build one unified registry out of the legacy DBs + new topics
// ------------------------------------------------------------
const TOPICS = {};
(function buildRegistry() {
  const legacyEmoji = { food: "🍜", animals: "🦫", technology: "💻" };
  Object.keys(DOMAINS).forEach(id => {
    const d = DOMAINS[id];
    TOPICS[id] = {
      id: id, label: d.label, emoji: legacyEmoji[id] || "✨",
      questions: d.order.filter(k => k !== "random").map(k => ({
        id: k, q: d.db[k].prompt, hint: d.db[k].hint, items: d.db[k].items, wiki: LEGACY_WIKI[k] || []
      }))
    };
  });
  Object.keys(EXTRA_TOPICS).forEach(id => {
    const t = EXTRA_TOPICS[id];
    TOPICS[id] = {
      id: id, label: t.label, emoji: t.emoji,
      questions: t.questions.map(q => ({ id: q.id, q: q.q, hint: q.hint, pool: q.pool, wiki: t.wikiOff ? null : (q.wiki || []) }))
    };
  });
})();

